fun {ι} [Fintype ι] [DecidableEq ι] =>
  { fintypeObj := inferInstance,
    fintypeHom := fun x x_1 =>
      match x, x_1 with
      | CategoryTheory.Pairwise.single i, CategoryTheory.Pairwise.single j =>
        { elems := if h : i = j then {CategoryTheory.eqToHom ⋯} else ∅, complete := ⋯ }
      | CategoryTheory.Pairwise.single i, CategoryTheory.Pairwise.pair j k =>
        { elems := ∅, complete := ⋯ }
      | CategoryTheory.Pairwise.pair i j, CategoryTheory.Pairwise.single k =>
        {
          elems :=
            (if h : i = k then
                {CategoryTheory.CategoryStruct.comp (CategoryTheory.Pairwise.Hom.left i j)
                    (CategoryTheory.eqToHom ⋯)}
              else ∅) ∪
              if h : j = k then
                {CategoryTheory.CategoryStruct.comp (CategoryTheory.Pairwise.Hom.right i j)
                    (CategoryTheory.eqToHom ⋯)}
              else ∅,
          complete := ⋯ }
      | CategoryTheory.Pairwise.pair i j, CategoryTheory.Pairwise.pair k l =>
        { elems := if h : i = k ∧ j = l then {CategoryTheory.eqToHom ⋯} else ∅, complete := ⋯ } }

